  // values, not reset zeros. Gate = SMODE (ax66_makatau registration).
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.satp    = 0x0000000000000000ULL;  // paging off inside the ROI envelope
  s.medeleg = 0x000000000000B109ULL;
  s.mideleg = 0x0000000000000222ULL;

  hybrid::AndesCaps smode = hybrid::AndesCaps::none();
  smode.set(hybrid::AndesGate::SMODE);

