  CHECK(contains_regno(ns, hybrid::regno_csr(0x302)));  // medeleg
  CHECK(contains_regno(ns, hybrid::regno_csr(0x303)));  // mideleg

  // medeleg's write COMMAND carries its value on DATA0/DATA1
  std::optional<std::size_t> cmd_idx;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xFFFFu) == hybrid::regno_csr(0x302)
        && ((op.value >> 16) & 1u)) {
      cmd_idx = i;
      break;
    }
  }
  REQUIRE(cmd_idx.has_value());
  const auto& d0 = bus.ops[*cmd_idx - 2];
  const auto& d1 = bus.ops[*cmd_idx - 1];
  CHECK(d0.reg == kData0);
  CHECK(d0.value == uint32_t(s.medeleg & 0xFFFFFFFFu));
  CHECK(d1.reg == kData1);
  CHECK(d1.value == uint32_t(s.medeleg >> 32));
}

