1	// Oracle differential compare. See state_diff.hpp for the policy.
2	#include "state_diff.hpp"
3	
4	#include <cstdio>
5	#include <string>
6	#include <string_view>
7	
8	namespace andes_sim {
9	
10	namespace {
11	
12	void cmp(DiffReport& r, const std::string& field, unsigned long long ref,
13	         unsigned long long got) {
14	  ++r.compared;
15	  if (ref != got) r.diffs.push_back({field, ref, got});
16	}
17	
18	}  // namespace
19	
20	DiffReport diff_states(const hybrid_state_v1& ref, const hybrid_state_v1& got,
21	                       const std::vector<std::string>& andes_supported) {
22	  DiffReport r;
23	
24	  cmp(r, "magic", ref.magic, got.magic);
25	  cmp(r, "version", ref.version, got.version);
26	  cmp(r, "flags", ref.flags, got.flags);
27	  cmp(r, "hart_id", ref.hart_id, got.hart_id);
28	  cmp(r, "priv", ref.priv, got.priv);
29	  cmp(r, "pc", ref.pc, got.pc);
30	
31	  // mepc/mcause: in the trap-free hybrid ROI they round-trip (L24: restored at
32	  // resume, re-read at drain). mtval/mstatus stay out of scope where they are
33	  // implementation-defined / carry dirty bits (false positives).
34	  cmp(r, "mepc", ref.mepc, got.mepc);
35	  cmp(r, "mcause", ref.mcause, got.mcause);
36	
37	  // Round-trip M-mode CSRs: mscratch (L23) and mtval/mie (L24) are restored at
38	  // resume and re-read at drain, so a trap-free ROI must match the oracle on
39	  // them. mip is excluded: its pending bits are hardware/platform-driven
40	  // (timer/external) and diverge between QEMU's functional clock and vsim's
41	  // cycle clock even with no trap (it still round-trips into the drained
42	  // record, just not the verifier).
43	  cmp(r, "mscratch", ref.mscratch, got.mscratch);
44	  cmp(r, "mtval", ref.mtval, got.mtval);
45	  cmp(r, "mie", ref.mie, got.mie);
46	
47	  for (int i = 0; i < 32; ++i)
48	    cmp(r, "x" + std::to_string(i), ref.gpr[i], got.gpr[i]);
49	
50	  if (ref.flags & HYBRID_FLAG_FP) {
51	    for (int i = 0; i < 32; ++i)
52	      cmp(r, "f" + std::to_string(i), ref.fpr[i], got.fpr[i]);
53	    cmp(r, "fcsr", ref.fcsr, got.fcsr);  // L20: frm + sticky fflags
54	  }
55	
56	  if (ref.flags & HYBRID_FLAG_V) {
57	    cmp(r, "vstart", ref.vstart, got.vstart);
58	    cmp(r, "vtype", ref.vtype, got.vtype);
59	    cmp(r, "vl", ref.vl, got.vl);
60	    cmp(r, "vlenb", ref.vlenb, got.vlenb);
61	    cmp(r, "vxsat", ref.vxsat, got.vxsat);
62	    cmp(r, "vxrm", ref.vxrm, got.vxrm);
63	    cmp(r, "vcsr", ref.vcsr, got.vcsr);
64	
65	    // One compared "field" per vector register; report the first differing
66	    // byte as "v<i>[<byte>]".
67	    for (int i = 0; i < 32; ++i) {
68	      ++r.compared;
69	      const uint8_t* a = &ref.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
70	      const uint8_t* b = &got.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
71	      for (int j = 0; j < HYBRID_VLEN_BYTES_MAX; ++j) {
72	        if (a[j] != b[j]) {
73	          r.diffs.push_back({"v" + std::to_string(i) + "[" +
74	                                 std::to_string(j) + "]",
75	                             a[j], b[j]});
76	          break;
77	        }
78	      }
79	    }
80	  }
81	
82	  // Andes V5 CSR block (v3): the boot-static memory-system/extension CSRs plus
83	  // the DSP overflow flag round-trip through the trap-free ROI (ResumeDriver
84	  // restores them, StateDrain re-reads them), so a correct transport matches the
85	  // oracle. The X-macro is the single source of truth shared with the plugin
86	  // drain / resume / drain re-read, so this list can never drift out of sync.
87	  //
88	  // Exclusion: msp_bound/msp_base are the HW stack-protection bound registers.
89	  // QEMU resets them to all-ones; a vsim core that does not implement HW stack
90	  // protection drains 0. That divergence is an engine-implementation artifact,
91	  // not a transport bug (the restore is a tolerant no-op on a core lacking the
92	  // CSR) -- so they are transported but excluded from strict verify, exactly
93	  // like mip's hardware-driven pending bits.
94	  auto andes_verify_excluded = [](std::string_view name) {
95	    // msp_bound/msp_base: engine-reset-divergent HW stack-protection bounds.
96	    // milmb/mdlmb: ILM/DLM base+enable CSRs. The base address round-trips, but
97	    // the enable bit (bit 0) is HW-presence state -- the vsim RTL has the local
98	    // memories and drains EN=1, while QEMU models none and drains EN=0. Same
99	    // class as msp_bound/msp_base (an engine-implementation artifact, not a
100	    // transport bug), so excluded rather than half-compared via a bit mask.
101	    // mhpmcounter3..6: hardware performance counters that increment DURING the
102	    // ROI, so the vsim (cycle) and QEMU (functional) values legitimately differ
103	    // -- transported and restored, but not strict-compared, like mcycle/mip.
104	    // mdcause: vsim models it as HW-set (a direct write drains back 0).
105	    // tdata1/tcontrol/mcontext: debug-trigger state whose reset defaults and
106	    // WARL widths differ between QEMU and vsim. All transported + restored, but
107	    // not cross-engine strict-compared.
108	    // mnvec: QEMU resets it to 0; the Andes RTL resets it to the hart's reset
109	    // vector and WARL-holds it (a restore write of 0 does not take), so a
110	    // trap-free ROI always false-diffs. Seen live on both engines when the
111	    // registration audit first claimed it (spec: "IM Requirement: Required").
112	    static constexpr std::string_view kExcluded[] = {
113	        "msp_bound", "msp_base", "milmb", "mdlmb",
114	        "mhpmcounter3", "mhpmcounter4", "mhpmcounter5", "mhpmcounter6",
115	        "mdcause", "tdata1", "tcontrol", "mcontext", "mnvec"};
116	    for (std::string_view e : kExcluded)
117	      if (e == name) return true;
118	    return false;
119	  };
120	  // Engine capability gate (S4): skip any Andes CSR the cycle engine does not
121	  // implement. Empty list = no engine info -> compare all (back-compat).
122	  auto andes_supported_csr = [&](std::string_view name) {
123	    if (andes_supported.empty()) return true;
124	    for (const std::string& s : andes_supported)
125	      if (s == name) return true;
126	    return false;
127	  };
128	  // v6 write-mask gate: skip any mask-governed CSR the program never WROTE
129	  // (per the oracle's mask, which covers boot + ROI). Unwritten CSRs hold
130	  // QEMU's reset default in `ref` but the engine's own RTL reset in `got`
131	  // (the restore skipped them too), so comparing would false-positive on
132	  // every reset-value divergence. Flag clear = pre-v6 file = compare all.
133	  auto wm_live = [&](int slot) {
134	    if (!(ref.flags & HYBRID_FLAG_WRITE_MASK)) return true;
135	    return hybrid_wm_test(ref.write_mask, static_cast<unsigned>(slot)) != 0;
136	  };
137	  if (ref.flags & HYBRID_FLAG_ANDES) {
138	#define X(field, addr, name)                                     \
139	  if (!andes_verify_excluded(name) && andes_supported_csr(name)  \
140	      && wm_live(HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_##field)) \
141	    cmp(r, name, ref.andes.field, got.andes.field);
142	    HYBRID_ANDES_CSR_LIST(X)
143	#undef X
144	    if (andes_supported_csr("pmacfg"))
145	      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
146	        if (wm_live(HYBRID_WM_PMACFG_BASE + i))
147	          cmp(r, "pmacfg" + std::to_string(i), ref.andes.pmacfg[i],
148	              got.andes.pmacfg[i]);
149	    if (andes_supported_csr("pmaaddr"))
150	      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
151	        if (wm_live(HYBRID_WM_PMAADDR_BASE + i))
152	          cmp(r, "pmaaddr" + std::to_string(i), ref.andes.pmaaddr[i],
153	              got.andes.pmaaddr[i]);
154	  }
155	
156	  // M-ext CSR block (v4): same gate (the engine's supported list now includes
157	  // the M-ext names) and the same HW-driven exclusion. A CSR the engine lacks
158	  // is neither restored, drained, nor compared.
159	  if (ref.flags & HYBRID_FLAG_M_EXT) {
160	#define X(field, addr, name)                                     \
161	  if (!andes_verify_excluded(name) && andes_supported_csr(name)  \
162	      && wm_live(HYBRID_WM_M_EXT_BASE + HYBRID_WM_M_EXT_IDX_##field)) \
163	    cmp(r, name, ref.m_ext.field, got.m_ext.field);
164	    HYBRID_M_EXT_CSR_LIST(X)
165	#undef X
166	  }
167	
168	  // L2C MMIO config (v5): the L2C Control Register round-trips (restored at
169	  // resume, re-read at drain), so compare its RW config bits (CEN, prefetch,
170	  // ECC, RAM timing). INITSTATUS[14] is a read-only status bit -- a real L2C
171	  // model drives it, QEMU's RAM stub does not -- so mask it to avoid a false
172	  // positive. Only the writable Control Register is verified; the read-only
173	  // Configuration Register and the volatile CCTL/error/counter registers are
174	  // captured but not restored, so they are not compared.
175	  if (ref.flags & HYBRID_FLAG_L2C) {
176	    const uint64_t rw_mask = ~(uint64_t{1} << 14);  // clear INITSTATUS[14]
177	    cmp(r, "l2c.ctrl",
178	        ref.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] & rw_mask,
179	        got.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] & rw_mask);
180	  }
181	
182	  return r;
183	}
184	
185	std::vector<std::string> unsupported_written_csrs(
186	    const hybrid_state_v1& st, const std::vector<std::string>& andes_supported) {
187	  std::vector<std::string> out;
188	  if (!(st.flags & HYBRID_FLAG_WRITE_MASK)) return out;  // pre-v6: no info
189	  if (andes_supported.empty()) return out;               // no engine info
190	
191	  const auto supported = [&](std::string_view name) {
192	    for (const std::string& s : andes_supported)
193	      if (s == name) return true;
194	    return false;
195	  };
196	  const auto written = [&](int slot) {
197	    return hybrid_wm_test(st.write_mask, static_cast<unsigned>(slot)) != 0;
198	  };
199	
200	  // Andes scalars. ucode is skipped: the plugin sets its bit unconditionally
201	  // (transport-always DSP flag), so it carries no real write information.
202	#define X(field, addr, name)                                              \
203	  if (std::string_view{name} != "ucode"                                   \
204	      && written(HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_##field)      \
205	      && !supported(name))                                                \
206	    out.push_back(name);
207	  HYBRID_ANDES_CSR_LIST(X)
208	#undef X
209	
210	  // PMA: one group marker each, matching the --describe list's convention.
211	  for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
212	    if (written(HYBRID_WM_PMACFG_BASE + i) && !supported("pmacfg")) {
213	      out.push_back("pmacfg");
214	      break;
215	    }
216	  for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
217	    if (written(HYBRID_WM_PMAADDR_BASE + i) && !supported("pmaaddr")) {
218	      out.push_back("pmaaddr");
219	      break;
220	    }
221	
222	#define X(field, addr, name)                                              \
223	  if (written(HYBRID_WM_M_EXT_BASE + HYBRID_WM_M_EXT_IDX_##field)         \
224	      && !supported(name))                                                \
225	    out.push_back(name);
226	  HYBRID_M_EXT_CSR_LIST(X)
227	#undef X
228	
229	  return out;
230	}
231	
232	std::string unsupported_written_warning(
233	    const hybrid_state_v1& st, const std::vector<std::string>& andes_supported,
234	    const std::string& engine_id) {
235	  const auto bad = unsupported_written_csrs(st, andes_supported);
236	  if (bad.empty()) return {};
237	  std::string names;
238	  for (const std::string& n : bad) {
239	    if (!names.empty()) names += ", ";
240	    names += n;
241	  }
242	  return "[andesim] warning: the program wrote CSRs engine " + engine_id +
243	         " does not implement: " + names +
244	         " (on this engine's silicon these writes would trap; the hybrid "
245	         "restore skipped them)\n";
246	}
247	
248	void print_diff_report(const DiffReport& r) {
249	  for (const FieldDiff& d : r.diffs)
250	    std::printf("[state-diff] %s: ref=0x%llx got=0x%llx\n", d.field.c_str(),
251	                d.ref, d.got);
252	  if (r.ok()) {
253	    std::printf(
254	        "[state-diff] PASS: %d fields match (counters and passthrough CSRs "
255	        "excluded)\n",
256	        r.compared);
257	  } else {
258	    std::printf("[state-diff] FAIL: %zu mismatch(es) (%d fields compared)\n",
259	                r.diffs.size(), r.compared);
260	  }
261	}
262	
263	}  // namespace andes_sim
